public class InnerCampaignCommunicationTimeConfigFactory(Action<Humidifier.ConnectCampaignsV2.CampaignTypes.CommunicationTimeConfig> factoryAction = null) : SubResourceFactory<Humidifier.ConnectCampaignsV2.CampaignTypes.CommunicationTimeConfig>
{

    internal InnerCampaignLocalTimeZoneConfigFactory LocalTimeZoneConfigFactory { get; set; }

    internal InnerCampaignTimeWindowFactory EmailFactory { get; set; }

    internal InnerCampaignTimeWindowFactory TelephonyFactory { get; set; }

    internal InnerCampaignTimeWindowFactory SmsFactory { get; set; }

    protected override Humidifier.ConnectCampaignsV2.CampaignTypes.CommunicationTimeConfig Create()
    {
        var communicationTimeConfigResult = CreateCommunicationTimeConfig();
        factoryAction?.Invoke(communicationTimeConfigResult);

        return communicationTimeConfigResult;
    }

    private Humidifier.ConnectCampaignsV2.CampaignTypes.CommunicationTimeConfig CreateCommunicationTimeConfig()
    {
        var communicationTimeConfigResult = new Humidifier.ConnectCampaignsV2.CampaignTypes.CommunicationTimeConfig();

        return communicationTimeConfigResult;
    }
    public override void CreateChildren(Humidifier.ConnectCampaignsV2.CampaignTypes.CommunicationTimeConfig result)
    {
        base.CreateChildren(result);

        result.LocalTimeZoneConfig ??= LocalTimeZoneConfigFactory?.Build();
        result.Email ??= EmailFactory?.Build();
        result.Telephony ??= TelephonyFactory?.Build();
        result.Sms ??= SmsFactory?.Build();
    }

} // End Of Class

